proxy = cli.String("proxy", cli.setVerboseName("代理IP"),cli.setCliGroup("config"))
domains = cli.Text("domains", cli.setVerboseName("域名"),cli.setCliGroup("config"))
cli.check()

# 白名单开启状态
status = false
if domains != ""{
    domains = str.ParseStringToLines(domains)
    status = true
}


# mirrorHTTPFlow 会镜像所有的流量到这里，包括 .js / .css / .jpg 这类一般会被劫持程序过滤的请求
mirrorHTTPFlow = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    if proxy == ""{
        return
    }
    if status{
        domain = str.ExtractHostPort(url)
        if str.StringContainsAnyOfSubString(domain, domains){
            _,_,err = poc.HTTP(req, poc.https(isHttps),poc.proxy(proxy),poc.timeout(5))
            if err != nil{
                yakit.Warn("%v 转发失败"%url)
            }
            return
        }
    }else{
        _,_,err = poc.HTTP(req, poc.https(isHttps),poc.proxy(proxy),poc.timeout(5))
        if err != nil{
            yakit.Warn("%v 转发失败"%url)
        }
        return
    }
}
